<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,newKey,ApiError} from '../api'
import {cacheGet,cacheSet} from '../platform/bridge'
import {useRequestScope} from '../platform/request-scope'
import {authorCost} from './cost'
import AuthorStartFields from './AuthorStartFields.vue'
import type {AuthorValue} from './types'
type Estimate={unlimitedUsage?:boolean;profileId:string;name:string;modelId:string;contextWindow:number;reservation:{maxCalls:number;inputTokens:number;outputTokens:number};remaining:{calls:number|null;inputTokens:number|null;outputTokens:number|null};moneyNote:string;models:{id:string;name:string;modelId:string;available:boolean}[]}
type Trial={unlimitedUsage?:boolean;worldId:string;lineId:string;originWorldId:string;authorVersion:number;requestId?:string;limits:{generations:number;inputTokens:number;outputTokens:number};reserved:{generations:number;inputTokens:number;outputTokens:number};tasks:{id:string;state:string;errorCode:string|null;providerState:string}[];budgetNote:string}
const props=defineProps<{worldId:string;value:AuthorValue;version:number;dirty:boolean;busy:boolean}>(),emit=defineEmits<{start:[];edit:[tab:string]}>(),route=useRoute(),router=useRouter(),scope=useRequestScope(()=>props.worldId,()=>route.path)
const estimate=ref<Estimate>(),profile=ref(''),opening=ref(''),values=ref<Record<string,string|number|boolean|string[]|null>>({}),maxGenerations=ref(5),inputLimit=ref(2000000),outputLimit=ref(500000),trials=ref<Trial[]>([]),active=ref(''),working=ref(false),error=ref(''),intent=ref<{body:Record<string,unknown>;key:string}>(),pending=ref(false)
const characterId=ref(''),customName=ref(''),customIdentity=ref(''),characters=computed(()=>props.value.definition.entities.filter(e=>e.type==='character'))
watch(()=>[opening.value,props.value.openings],()=>{const chosen=props.value.openings.find(o=>o.id===opening.value);characterId.value=chosen?.characterId||props.value.plot?.recommendedCharacterId||characters.value.find(e=>props.value.definition.initial[e.id]?.alive!==false)?.id||'custom'},{immediate:true,deep:true})
const slot='author-trial-intent:'+props.worldId,cost=computed(()=>authorCost(props.value,opening.value)),selected=computed(()=>trials.value.find(t=>t.worldId===active.value)),iframe=computed(()=>selected.value?.lineId?'/worlds/'+selected.value.worldId+'/play?line='+selected.value.lineId+'&embedded=author':''),core=computed(()=>cost.value.filter(p=>!p.conditional).reduce((s,p)=>s+p.high,0)),conditional=computed(()=>cost.value.filter(p=>p.conditional).reduce((s,p)=>s+p.high,0))
const budgetProblem=computed(()=>estimate.value?.unlimitedUsage?'':!Number.isInteger(maxGenerations.value)||maxGenerations.value<1||maxGenerations.value>20?'生成次数须为 1–20 的整数。':!Number.isInteger(inputLimit.value)||inputLimit.value<1000||inputLimit.value>10000000?'输入预留上限须为 1,000–10,000,000 的整数。':!Number.isInteger(outputLimit.value)||outputLimit.value<1000||outputLimit.value>2000000?'输出预留上限须为 1,000–2,000,000 的整数。':estimate.value&&(inputLimit.value<estimate.value.reservation.inputTokens||outputLimit.value<estimate.value.reservation.outputTokens)?'当前预算不足以覆盖第一次文字请求的安全预留，请提高输入或输出上限。':'')
const taskLabel=(state?:string)=>({queued:'等待开始',preparing:'正在准备',calling:'正在生成',running:'正在生成',streaming:'正在生成',validating:'正在核对',saving:'正在保存',succeeded:'已完成',failed:'未完成',cancelled:'已停止'} as Record<string,string>)[state||'']||'等待处理'
let timer:ReturnType<typeof setTimeout>|undefined,modelEpoch=0,disposed=false
function proposeLimits(){if(estimate.value){inputLimit.value=Math.min(10000000,Math.max(1000,estimate.value.reservation.inputTokens*maxGenerations.value));outputLimit.value=Math.min(2000000,Math.max(1000,estimate.value.reservation.outputTokens*maxGenerations.value))}}
watch(maxGenerations,proposeLimits)
async function loadModel(){const current=++modelEpoch,check=scope();estimate.value=undefined;error.value='';try{const v=await api<Estimate>('/authoring/worlds/'+props.worldId+'/test-model'+(profile.value?'?profileId='+encodeURIComponent(profile.value):''));if(check.valid()&&current===modelEpoch){estimate.value=v;proposeLimits()}}catch(e){if(check.valid()&&current===modelEpoch)error.value=(e as Error).message}}
async function choose(trial:Trial){active.value=trial.worldId;await router.replace({path:route.path,query:{...route.query,trial:trial.worldId}})}
async function refresh(){const check=scope();try{const result=await api<{items:Trial[]}>('/authoring/worlds/'+props.worldId+'/trials');if(!check.valid()||disposed)return;trials.value=result.items;const requested=String(route.query.trial||'');if(!active.value)active.value=trials.value.find(t=>t.worldId===requested)?.worldId||trials.value[0]?.worldId||'';const found=intent.value&&trials.value.find(t=>t.requestId===intent.value?.key);if(found){intent.value=undefined;pending.value=false;await cacheSet(slot,null);await choose(found)};clearTimeout(timer);if(trials.value.some(t=>t.tasks.some(x=>!['succeeded','failed','cancelled'].includes(x.state))))timer=setTimeout(()=>void refresh(),2500)}catch(e){if(check.valid()&&!disposed)error.value=(e as Error).message}}
async function start(){if(working.value||props.dirty||!estimate.value||!intent.value&&budgetProblem.value)return;const check=scope();working.value=true;error.value='';try{if(!intent.value){const key=newKey();intent.value={key,body:{requestId:key,authorVersion:props.version,openingId:opening.value,playerValues:values.value,characterId:characterId.value==='custom'?null:characterId.value,customName:characterId.value==='custom'?customName.value:'',customIdentity:characterId.value==='custom'?customIdentity.value:'',profileId:profile.value||null,maxGenerations:maxGenerations.value,maxInputTokens:inputLimit.value,maxOutputTokens:outputLimit.value,lineName:'作者试玩 · 版本 '+props.version}};await cacheSet(slot,intent.value)}pending.value=true;const response=await api<{worldId:string}>('/authoring/worlds/'+props.worldId+'/trials',{method:'POST',body:intent.value.body,key:intent.value.key});if(!check.valid()||disposed)return;active.value=response.worldId;intent.value=undefined;pending.value=false;await cacheSet(slot,null);await refresh();const trial=trials.value.find(t=>t.worldId===response.worldId);if(trial)await choose(trial)}catch(e){if(check.valid()&&!disposed){error.value=(e as Error).message;if(e instanceof ApiError&&e.status>=400&&e.status<500){intent.value=undefined;pending.value=false;await cacheSet(slot,null)}await refresh()}}finally{if(check.valid())working.value=false}}
defineExpose({start})
onMounted(async()=>{const check=scope();const saved=await cacheGet<typeof intent.value>(slot);if(!check.valid())return;if(saved){intent.value=saved;pending.value=true}await Promise.allSettled([loadModel(),refresh()])})
onUnmounted(()=>{disposed=true;clearTimeout(timer)})
</script>
<template><section class="author-trial-panel" aria-label="保存后试玩与成本预算"><h2>保存后试玩</h2><p>冻结本次作者配置，创建独立的私人测试世界。玩家主线、已发布版本与原结局保持原状。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="pending" role="status">上次创建回执待核对。先刷新记录，继续提交会使用原请求编号，不另建重复任务。</p>
<div class="trial-setup"><section><h3>选择测试开局</h3><AuthorStartFields :config="value" v-model:opening-id="opening" v-model:values="values"/><label>本次扮演人物<select aria-label="本次扮演人物" v-model="characterId"><option v-for="person in characters" :key="person.id" :value="person.id" :disabled="value.definition.initial[person.id]?.alive===false">{{person.name}}</option><option value="custom">创建自定义身份</option></select></label><template v-if="characterId==='custom'"><p>你将以新人物行动，原故事人物仍保留。请勿使用已有角色同名；若要扮演原角色，直接选择该人物。</p><label>试玩人物名字<input v-model="customName" maxlength="80"></label><label>试玩人物身份<textarea v-model="customIdentity" maxlength="800"></textarea></label></template><label>试玩文本模型<select aria-label="试玩文本模型" v-model="profile" @change="loadModel"><option value="">账号当前默认</option><option v-for="model in estimate?.models||[]" :key="model.id" :value="model.id" :disabled="!model.available">{{model.name}} · {{model.modelId}}{{model.available?'':'（不可用）'}}</option></select></label><p v-if="estimate">本次：{{estimate.name}} · 上下文 {{estimate.contextWindow.toLocaleString()}} tokens</p><p v-else role="status">{{error?'模型预算尚未就绪':'正在读取模型预算…'}} <button v-if="error" @click="loadModel">重新读取模型预算</button></p><p v-if="estimate?.unlimitedUsage" role="status">内测不限额度：文字、图像和试玩次数均不限制；实际用量继续记录。</p><label v-show="!estimate?.unlimitedUsage">最多生成次数（含开场）<input type="number" v-model.number="maxGenerations" min="1" max="20"></label><label v-show="!estimate?.unlimitedUsage">输入 token 总预留上限<input type="number" v-model.number="inputLimit" min="1000" max="10000000"></label><label v-show="!estimate?.unlimitedUsage">输出 token 总预留上限<input type="number" v-model.number="outputLimit" min="1000" max="2000000"></label><p v-if="estimate">单次文字请求最多预留 {{estimate.reservation.maxCalls}} 次模型调用、{{estimate.reservation.inputTokens.toLocaleString()}} 输入和 {{estimate.reservation.outputTokens.toLocaleString()}} 输出 tokens。此为安全上限，不是本次实际消费。</p><p v-if="budgetProblem&&!pending" role="alert" class="error">{{budgetProblem}}</p><button class="primary" :disabled="working||busy||!estimate||!pending&&!!budgetProblem" @click="emit('start')">{{working?'正在创建试玩…':pending?'继续核对原创建请求':dirty||!version?'保存并开始试玩':'用已保存版本开始试玩'}}</button><button :disabled="working" @click="refresh">刷新试玩回执</button></section>
<section class="cost-card"><h3>设定量与成本提示</h3><p>随当前编辑实时变化。按当前选择的开局估算；运行时还会加入实际选择、状态、历史和系统指令。</p><dl><template v-for="part in cost" :key="part.id"><dt>{{part.title}}</dt><dd>{{part.characters.toLocaleString()}} 字符 · 约 {{part.low.toLocaleString()}}–{{part.high.toLocaleString()}} tokens</dd></template></dl><p>核心材料约不超过 {{core.toLocaleString()}} tokens；人物和知识全部触发时另约不超过 {{conditional.toLocaleString()}} tokens。未触发内容不会被当作全部常驻。</p><p>{{estimate?.moneyNote||'金额未知：需要可核验单价和实际用量才能结算。'}}</p><p v-if="estimate">通道剩余：{{estimate.remaining.calls===null?'调用次数不限':estimate.remaining.calls+' 次调用'}}；输入 {{estimate.remaining.inputTokens?.toLocaleString()||'不限'}}、输出 {{estimate.remaining.outputTokens?.toLocaleString()||'不限'}} tokens。试玩预算不增加通道额度。</p><p>设定量估算不含图像识别开销。{{estimate?.unlimitedUsage?'内测试玩也支持图像，不限文字和图像额度。':'作者试玩目前限定文字请求；图像需要单独预算。'}}失败或未知结果不退还本条测试的预留，不会自动重发。</p></section></div>
<section class="trial-history"><h3>已保存的试玩记录</h3><p v-if="!trials.length">还没有试玩。先确认开局和预算，再开始测试。</p><button v-for="trial in trials" :key="trial.worldId" :aria-pressed="active===trial.worldId" @click="choose(trial)">配置 {{trial.authorVersion}} · 已预留 {{trial.reserved.generations}} / {{trial.unlimitedUsage?'不限':trial.limits.generations}} 次 · {{taskLabel(trial.tasks.at(-1)?.state)}}</button></section><section v-if="selected" class="trial-current"><h3>当前试玩 · 配置版本 {{selected.authorVersion}}</h3><p>{{selected.budgetNote}}</p><p>已预留：{{selected.reserved.inputTokens.toLocaleString()}} / {{selected.unlimitedUsage?'不限':selected.limits.inputTokens.toLocaleString()}} 输入，{{selected.reserved.outputTokens.toLocaleString()}} / {{selected.unlimitedUsage?'不限':selected.limits.outputTokens.toLocaleString()}} 输出 tokens。</p><ul><li v-for="task in selected.tasks" :key="task.id"><span>查看任务回执</span> · {{taskLabel(task.state)}}<span v-if="task.errorCode"> · {{task.errorCode}}</span><span v-if="task.providerState==='unknown'"> · 供应商结果未知，禁止自动重发</span></li></ul><div class="trial-corrections"><button @click="emit('edit','fields')">回画布调整字段</button><button @click="emit('edit','world')">调整人物与初始状态</button><button @click="emit('edit','plot')">调整任务和结局</button><button @click="emit('edit','openings')">调整开局</button></div><p>调整并保存后另开试玩。当前测试继续使用原配置。</p><iframe v-if="iframe" :key="iframe" :src="iframe" title="作者真实游玩测试" class="trial-frame"></iframe></section></section></template>
<style scoped>.trial-setup{display:grid;grid-template-columns:1fr 1fr;gap:24px}.trial-setup>section{min-width:0;padding:20px;border:1px solid var(--line,#e8e1d8);border-radius:12px}.trial-setup label{display:block;margin:16px 0}.trial-setup input,.trial-setup select{width:100%;min-height:44px}.cost-card dt{font-weight:600;margin-top:12px}.cost-card dd{margin:4px 0;color:var(--muted,#766b60)}.trial-history button,.trial-corrections button{margin:4px;min-height:44px}.trial-current{margin-top:24px}.trial-frame{width:100%;height:850px;border:1px solid var(--line,#e8e1d8);border-radius:12px;background:var(--paper,#fffdf9)}@media(max-width:900px){.trial-setup{grid-template-columns:1fr}}</style>
